export const BAGIAN = [{"id":"panduan-1","bab":"bab-bidak","nomor":"1","judul":"♙ PION (Pawn)","deskripsi":"Pion adalah bidak paling dasar dalam catur, tetapi punya peran sangat penting dalam permainan. Meski gerakannya terlihat sederhana, pion sangat kuat untuk mengontrol ruang, membuka jalan serangan, dan mendukung bidak lain. Pion bergerak maju lurus, namun menangkap lawan secara diagonal, sehingga pemain harus memahami perbedaan gerak dan makannya dengan benar.","baris":[{"sub":false,"html":"<div class=\"content-row\">\n        <div class=\"board-panel relative\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <!-- Papan 8×8 -->\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect x=\"0\"   y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"150\" y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"100\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"150\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"175\" width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"175\" width=\"25\" height=\"25\"/>\n                </g>\n\n                <!-- Highlight: maju 1 kotak (e5) dan maju 2 kotak (e6) -->\n                <rect x=\"100\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.55\"/>\n                <rect x=\"100\" y=\"75\"  width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.40\"/>\n                <!-- Highlight: makan diagonal -->\n                <rect x=\"75\"  y=\"100\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.35\"/>\n                <rect x=\"125\" y=\"100\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.35\"/>\n\n                <!-- Titik arah maju -->\n                <circle cx=\"112.5\" cy=\"112.5\" r=\"5\" fill=\"#facc15\" fill-opacity=\"0.80\"/>\n                <circle cx=\"112.5\" cy=\"87.5\"  r=\"5\" fill=\"#facc15\" fill-opacity=\"0.60\"/>\n                <!-- Titik makan diagonal -->\n                <circle cx=\"87.5\"  cy=\"112.5\" r=\"5\" fill=\"#ef4444\" fill-opacity=\"0.70\"/>\n                <circle cx=\"137.5\" cy=\"112.5\" r=\"5\" fill=\"#ef4444\" fill-opacity=\"0.70\"/>\n\n                <!-- Pion putih di e4 (y=125) -->\n                <text x=\"112.5\" y=\"137.5\" font-size=\"20\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♙</text>\n\n                <!-- Label -->\n                <text x=\"100\" y=\"10\" font-size=\"7\" fill=\"white\"\n                      text-anchor=\"middle\" font-weight=\"bold\" opacity=\"0.90\">GERAKAN PION</text>\n\n                <!-- Koordinat kolom -->\n                <text x=\"112.5\" y=\"209\" font-size=\"5.5\" fill=\"#374151\"\n                      text-anchor=\"middle\" font-weight=\"bold\">e</text>\n                <text x=\"87.5\"  y=\"209\" font-size=\"5.5\" fill=\"#374151\"\n                      text-anchor=\"middle\" font-weight=\"bold\">d</text>\n                <text x=\"137.5\" y=\"209\" font-size=\"5.5\" fill=\"#374151\"\n                      text-anchor=\"middle\" font-weight=\"bold\">f</text>\n                <text x=\"100\" y=\"219\" font-size=\"7.5\" fill=\"#374151\"\n                      text-anchor=\"middle\" font-weight=\"bold\">♙ GERAKAN DASAR PION</text>\n            </svg>\n\n            <div style=\"display:flex;gap:8px;margin-top:4px;justify-content:center;flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:7.5px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#facc15;border-radius:50%;display:inline-block;opacity:.8\"></span>\n                    Gerak maju (1 atau 2 kotak)\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:7.5px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#ef4444;border-radius:50%;display:inline-block;opacity:.8\"></span>\n                    Makan diagonal\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Nilai: 1 Poin</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Pion adalah bidak dengan nilai 1 poin dan merupakan bidak yang paling banyak hadir di papan sejak awal permainan. Meski nilainya kecil, pion memiliki peran yang jauh lebih besar dari angka itu mencerminkan: ia mengontrol ruang, membentuk struktur pertahanan, membuka jalur serangan bagi bidak lain, dan dalam kondisi tertentu mampu mengubah jalannya pertandingan sepenuhnya.\n                <br><br>\n                Pion bergerak maju satu kotak setiap giliran. Pada langkah pertamanya saja, ia diberi hak istimewa untuk maju dua kotak sekaligus, selama tidak ada bidak yang menghalangi jalurnya. Setelah langkah pertama itu digunakan, hak tersebut gugur dan pion hanya boleh melangkah satu kotak per giliran untuk seterusnya.\n                <br><br>\n                Cara makan pion berbeda dari cara geraknya, dan inilah yang sering membingungkan pemain baru. Pion tidak bisa menangkap bidak lawan yang berada tepat di depannya. Ia hanya bisa makan secara diagonal — satu kotak serong ke depan, ke kiri atau ke kanan. Karena itu, pion yang berhadapan langsung dengan pion lawan di kolom yang sama akan saling memblok tanpa bisa saling memakan, kecuali salah satu menyerang dari sisi yang berbeda.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: left; margin-right: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <!-- Papan 8×8 -->\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect x=\"0\"   y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"150\" y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"100\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"150\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"175\" width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"175\" width=\"25\" height=\"25\"/>\n                </g>\n\n                <defs>\n                    <marker id=\"arr-ep-blk\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n                        <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#374151\"/></marker>\n                    <marker id=\"arr-ep-grn\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n                        <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#16a34a\"/></marker>\n                </defs>\n\n                <!--\n                    EN PASSANT:\n                    Pion hitam d7 (87.5,37.5) maju 2 kotak ke d5 (87.5,87.5)\n                    Pion putih e5 (112.5,87.5) bisa en passant ke d6 (87.5,62.5)\n                    Pion hitam d5 diambil dari papan.\n                -->\n\n                <!-- Highlight jalur pion hitam d7→d5 -->\n                <rect x=\"75\" y=\"25\"  width=\"25\" height=\"25\" fill=\"#94a3b8\" fill-opacity=\"0.25\"/>\n                <rect x=\"75\" y=\"50\"  width=\"25\" height=\"25\" fill=\"#94a3b8\" fill-opacity=\"0.15\"/>\n                <rect x=\"75\" y=\"75\"  width=\"25\" height=\"25\" fill=\"#94a3b8\" fill-opacity=\"0.30\"/>\n\n                <!-- Highlight kotak tujuan en passant d6 -->\n                <rect x=\"75\" y=\"50\"  width=\"25\" height=\"25\" fill=\"#22c55e\" fill-opacity=\"0.42\"/>\n\n                <!-- Pion hitam bayangan di d7 (posisi awal) -->\n                <text x=\"87.5\" y=\"37.5\" font-size=\"18\" fill=\"black\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.28\">♟</text>\n\n                <!-- Panah pion hitam d7→d5 -->\n                <line x1=\"87.5\" y1=\"44\" x2=\"87.5\" y2=\"84\"\n                      stroke=\"#374151\" stroke-width=\"1.8\" stroke-dasharray=\"3,2\"\n                      marker-end=\"url(#arr-ep-blk)\"/>\n\n                <!-- Pion hitam di d5 -->\n                <text x=\"87.5\" y=\"87.5\" font-size=\"20\" fill=\"black\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♟</text>\n\n                <!-- Pion putih di e5 -->\n                <text x=\"112.5\" y=\"87.5\" font-size=\"20\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♙</text>\n\n                <!-- Panah en passant: pion putih e5 → d6 -->\n                <line x1=\"108\" y1=\"84\" x2=\"92\" y2=\"68\"\n                      stroke=\"#16a34a\" stroke-width=\"2\"\n                      marker-end=\"url(#arr-ep-grn)\"/>\n\n                <!-- Tanda × di pion hitam d5 (dimakan) -->\n                <g stroke=\"#ef4444\" stroke-width=\"2.2\" opacity=\"0.75\">\n                    <line x1=\"81\" y1=\"81\" x2=\"94\" y2=\"94\"/>\n                    <line x1=\"94\" y1=\"81\" x2=\"81\" y2=\"94\"/>\n                </g>\n\n                <!-- Label baris -->\n                <text x=\"196\" y=\"40\"  font-size=\"5.5\" fill=\"white\" text-anchor=\"end\" opacity=\"0.70\">7</text>\n                <text x=\"196\" y=\"65\"  font-size=\"5.5\" fill=\"white\" text-anchor=\"end\" opacity=\"0.70\">6</text>\n                <text x=\"196\" y=\"90\"  font-size=\"5.5\" fill=\"white\" text-anchor=\"end\" opacity=\"0.70\">5</text>\n\n                <!-- Koordinat kolom -->\n                <text x=\"87.5\"  y=\"209\" font-size=\"5.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">d</text>\n                <text x=\"112.5\" y=\"209\" font-size=\"5.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">e</text>\n                <text x=\"100\"   y=\"219\" font-size=\"7.5\" fill=\"#15803d\" text-anchor=\"middle\" font-weight=\"bold\">♙ EN PASSANT</text>\n            </svg>\n\n            <div style=\"display:flex;gap:6px;margin-top:4px;justify-content:center;flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:7.5px;color:#555;\">\n                    <span style=\"width:7px;height:7px;background:#374151;border-radius:2px;display:inline-block;opacity:.7\"></span>\n                    Hitam maju 2 (d7→d5)\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:7.5px;color:#555;\">\n                    <span style=\"width:7px;height:7px;background:#22c55e;border-radius:2px;display:inline-block;opacity:.8\"></span>\n                    Tujuan en passant (d6)\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:7.5px;color:#555;\">\n                    <span style=\"width:7px;height:7px;background:#ef4444;border-radius:2px;display:inline-block;opacity:.7\"></span>\n                    Pion hitam dimakan\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Aturan Spesial: En Passant</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                <em>En passant</em> — dari bahasa Prancis, secara harfiah berarti \"sambil lewat\" — adalah salah satu aturan paling unik dalam catur dan berlaku secara eksklusif untuk pion. Aturan ini muncul dari situasi yang sangat spesifik: ketika pion lawan memanfaatkan hak maju dua kotak pada langkah pertamanya dan mendarat tepat di samping pion milik kita, seolah ia \"melewati\" petak yang seharusnya bisa dijadikan sasaran tangkap.\n                <br><br>\n                Perhatikan diagram. Pion hitam berada di <strong>d7</strong> dan maju dua kotak langsung ke <strong>d5</strong>, berhenti tepat di samping pion putih yang ada di <strong>e5</strong>. Dalam situasi ini, pion putih memiliki hak untuk menangkap pion hitam tersebut secara diagonal ke kotak <strong>d6</strong> — seolah pion hitam hanya melangkah satu kotak saja. Pion hitam di d5 diambil dari papan, meskipun pion putih tidak mendarat di petak yang ditempatinya.\n                <br><br>\n                Yang perlu diperhatikan adalah jendela waktu pelaksanaannya. Hak <em>en passant</em> hanya berlaku pada giliran langsung setelah pion lawan melakukan lompatan dua kotak. Jika kesempatan itu dilewatkan — bahkan hanya satu giliran — hak tersebut gugur selamanya untuk pion hitam yang sama. Tidak ada penundaan, tidak ada pengecualian.\n                <br><br>\n                <span class=\"bg-amber-50 border border-amber-200 px-2 py-1 rounded text-xs inline-block mt-1\">\n                    ⚠️ <strong>Penting:</strong> En passant hanya bisa dilakukan segera pada giliran berikutnya setelah pion lawan maju dua kotak. Jika tidak langsung digunakan, hak ini hangus dan tidak bisa dipakai lagi.\n                </span>\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 280\" class=\"w-full h-full\">\n                <!-- Papan 8×8 -->\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect x=\"0\"   y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"150\" y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"100\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"150\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"175\" width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"175\" width=\"25\" height=\"25\"/>\n                </g>\n\n                <defs>\n                    <marker id=\"arr-promo\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n                        <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#7c3aed\"/></marker>\n                </defs>\n\n                <!--\n                    PROMOSI PION:\n                    Pion putih di e7 (112.5,37.5) maju ke e8 (112.5,12.5)\n                    Zona promosi = rank 8 (y=0..25)\n                -->\n\n                <!-- Highlight zona promosi (rank 8) -->\n                <rect x=\"0\" y=\"0\" width=\"200\" height=\"25\" fill=\"#7c3aed\" fill-opacity=\"0.18\"/>\n                <rect x=\"0\" y=\"0\" width=\"200\" height=\"25\" fill=\"none\"\n                      stroke=\"#7c3aed\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/>\n\n                <!-- Label zona promosi -->\n                <text x=\"100\" y=\"12\" font-size=\"6\" fill=\"#6d28d9\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\"\n                      font-weight=\"bold\" letter-spacing=\"0.5\">★ ZONA PROMOSI ★</text>\n\n                <!-- Highlight petak e7 (pion siap) -->\n                <rect x=\"100\" y=\"25\" width=\"25\" height=\"25\" fill=\"#7c3aed\" fill-opacity=\"0.28\"/>\n\n                <!-- Pion putih di e7 -->\n                <text x=\"112.5\" y=\"37.5\" font-size=\"20\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♙</text>\n\n                <!-- Panah promosi e7→e8 -->\n                <line x1=\"112.5\" y1=\"30\" x2=\"112.5\" y2=\"16\"\n                      stroke=\"#7c3aed\" stroke-width=\"2.5\"\n                      marker-end=\"url(#arr-promo)\"/>\n\n                <!-- Label baris -->\n                <text x=\"4\" y=\"13\"  font-size=\"6\" fill=\"#7c3aed\" text-anchor=\"start\" font-weight=\"bold\">8</text>\n                <text x=\"4\" y=\"38\"  font-size=\"6\" fill=\"white\"   text-anchor=\"start\" opacity=\"0.65\">7</text>\n\n                <!-- Koordinat kolom -->\n                <text x=\"112.5\" y=\"207\" font-size=\"5.5\" fill=\"#374151\"\n                      text-anchor=\"middle\" font-weight=\"bold\">e</text>\n\n                <!-- Panel pilihan promosi -->\n                <rect x=\"8\" y=\"213\" width=\"184\" height=\"55\" rx=\"6\"\n                      fill=\"#f8fafc\" stroke=\"#7c3aed\" stroke-width=\"1\"/>\n\n                <text x=\"100\" y=\"225\" font-size=\"6\" fill=\"#6d28d9\"\n                      text-anchor=\"middle\" font-weight=\"bold\">PILIH PROMOSI:</text>\n\n                <!-- Ratu (direkomendasikan) -->\n                <rect x=\"14\" y=\"230\" width=\"36\" height=\"28\" rx=\"4\"\n                      fill=\"#ede9fe\" stroke=\"#7c3aed\" stroke-width=\"1.2\"/>\n                <text x=\"32\" y=\"244\" font-size=\"15\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♕</text>\n                <text x=\"32\" y=\"256\" font-size=\"5\" fill=\"#6d28d9\"\n                      text-anchor=\"middle\" font-weight=\"bold\">RATU ★</text>\n\n                <!-- Benteng -->\n                <rect x=\"58\" y=\"230\" width=\"36\" height=\"28\" rx=\"4\"\n                      fill=\"#f1f5f9\" stroke=\"#cbd5e1\" stroke-width=\"0.8\"/>\n                <text x=\"76\" y=\"244\" font-size=\"15\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♖</text>\n                <text x=\"76\" y=\"256\" font-size=\"5\" fill=\"#64748b\"\n                      text-anchor=\"middle\">BENTENG</text>\n\n                <!-- Gajah -->\n                <rect x=\"102\" y=\"230\" width=\"36\" height=\"28\" rx=\"4\"\n                      fill=\"#f1f5f9\" stroke=\"#cbd5e1\" stroke-width=\"0.8\"/>\n                <text x=\"120\" y=\"244\" font-size=\"15\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♗</text>\n                <text x=\"120\" y=\"256\" font-size=\"5\" fill=\"#64748b\"\n                      text-anchor=\"middle\">GAJAH</text>\n\n                <!-- Kuda -->\n                <rect x=\"146\" y=\"230\" width=\"36\" height=\"28\" rx=\"4\"\n                      fill=\"#f1f5f9\" stroke=\"#cbd5e1\" stroke-width=\"0.8\"/>\n                <text x=\"164\" y=\"244\" font-size=\"15\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♘</text>\n                <text x=\"164\" y=\"256\" font-size=\"5\" fill=\"#64748b\"\n                      text-anchor=\"middle\">KUDA</text>\n\n                <text x=\"100\" y=\"275\" font-size=\"7.5\" fill=\"#7c3aed\"\n                      text-anchor=\"middle\" font-weight=\"bold\">♙ PROMOSI PION</text>\n            </svg>\n\n            <div style=\"display:flex;gap:6px;margin-top:4px;justify-content:center;flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:7.5px;color:#555;\">\n                    <span style=\"width:7px;height:7px;background:#7c3aed;border-radius:2px;display:inline-block;opacity:.7\"></span>\n                    Zona promosi (rank 8)\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:7.5px;color:#555;\">\n                    <span style=\"width:7px;height:7px;background:#ede9fe;border:1px solid #7c3aed;border-radius:2px;display:inline-block;\"></span>\n                    Pilihan bidak\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Aturan Spesial: Promosi Pion</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Promosi pion adalah momen yang paling dramatis dalam perjalanan sebuah pion. Ketika pion putih berhasil mencapai <strong>baris ke-8</strong> — atau pion hitam mencapai baris ke-1 — ia tidak boleh berhenti menjadi pion. Ia wajib segera dipromosikan menjadi bidak lain: ratu, benteng, gajah, atau kuda. Tidak ada pilihan untuk melewati aturan ini.\n                <br><br>\n                Perhatikan diagram. Pion putih berada di <strong>e7</strong>, hanya satu langkah dari zona promosi yang ditandai ungu. Begitu pion melangkah ke <strong>e8</strong>, pemain harus memilih salah satu dari empat bidak di panel bawah sebagai gantinya.\n                <br><br>\n                Dalam hampir semua situasi, pilihan yang paling kuat adalah ratu karena ia adalah bidak dengan mobilitas tertinggi di papan. Namun ada kalanya memilih kuda justru lebih menguntungkan, terutama ketika kuda tersebut bisa langsung memberikan skak atau skakmat dalam pola yang tidak bisa dilakukan oleh ratu.\n                <br><br>\n            </p>\n            <div style=\"display:flex;gap:8px;margin:8px 0;flex-wrap:wrap;\">\n                <span style=\"background:#f3e8ff;border:1px solid #c4b5fd;padding:4px 10px;border-radius:6px;font-size:12px;font-weight:bold;color:#6d28d9;\">♕ Ratu</span>\n                <span style=\"background:#f1f5f9;border:1px solid #cbd5e1;padding:4px 10px;border-radius:6px;font-size:12px;color:#475569;\">♖ Benteng</span>\n                <span style=\"background:#f1f5f9;border:1px solid #cbd5e1;padding:4px 10px;border-radius:6px;font-size:12px;color:#475569;\">♗ Gajah</span>\n                <span style=\"background:#f1f5f9;border:1px solid #cbd5e1;padding:4px 10px;border-radius:6px;font-size:12px;color:#475569;\">♘ Kuda</span>\n            </div>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                <span class=\"bg-purple-50 border border-purple-200 px-2 py-1 rounded text-xs inline-block mt-1\">\n                    💡 <strong>Tips:</strong> Di fase akhir permainan, meloloskan pion hingga mencapai baris promosi sering kali menjadi penentu kemenangan. Pion yang tampak tidak berbahaya di tengah permainan bisa berubah menjadi ratu dalam beberapa langkah.\n                </span>\n                <br><br>\n                <span class=\"bg-blue-50 border border-blue-200 px-2 py-1 rounded text-xs inline-block\">\n                    📌 <strong>Catatan:</strong> Secara teoritis, sebuah pemain bisa memiliki hingga sembilan ratu sekaligus di papan — satu ratu asli ditambah delapan pion yang semuanya berhasil dipromosikan.\n                </span>\n            </p>\n        </div>\n    </div>"}]},{"id":"panduan-2","bab":"bab-bidak","nomor":"2","judul":"♞ KUDA (Knight)","deskripsi":"Kuda adalah bidak unik dalam catur karena gerakannya berbeda dari semua bidak lain. Jika bidak lain bergerak lurus atau diagonal, kuda bergerak dengan pola berbentuk huruf \"L\". Kuda juga memiliki kemampuan spesial yang membuatnya sangat berbahaya: ia bisa melompati bidak lain.","baris":[{"sub":false,"html":"<div class=\"content-row\">\n        <div class=\"board-panel relative\" style=\"float: left; margin-right: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <!-- Papan 8×8 -->\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect x=\"0\"   y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"150\" y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"100\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"150\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"175\" width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"175\" width=\"25\" height=\"25\"/>\n                </g>\n\n                <!--\n                    Kuda putih di d4 (87.5, 112.5)\n                    8 petak tujuan L-move dari d4:\n                    c6 (62.5, 62.5)   — 1 kiri 2 atas\n                    e6 (112.5, 62.5)  — 1 kanan 2 atas\n                    b5 (37.5, 87.5)   — 2 kiri 1 atas\n                    f5 (137.5, 87.5)  — 2 kanan 1 atas\n                    b3 (37.5, 137.5)  — 2 kiri 1 bawah\n                    f3 (137.5, 137.5) — 2 kanan 1 bawah\n                    c2 (62.5, 162.5)  — 1 kiri 2 bawah\n                    e2 (112.5, 162.5) — 1 kanan 2 bawah\n                -->\n\n                <!-- Highlight 8 kotak tujuan kuda -->\n                <rect x=\"50\"  y=\"50\"  width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.55\"/>\n                <rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.55\"/>\n                <rect x=\"25\"  y=\"75\"  width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.55\"/>\n                <rect x=\"125\" y=\"75\"  width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.55\"/>\n                <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.55\"/>\n                <rect x=\"125\" y=\"125\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.55\"/>\n                <rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.55\"/>\n                <rect x=\"100\" y=\"150\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.55\"/>\n\n                <!-- Titik di setiap kotak tujuan -->\n                <circle cx=\"62.5\"  cy=\"62.5\"  r=\"5\" fill=\"#facc15\" fill-opacity=\"0.90\"/>\n                <circle cx=\"112.5\" cy=\"62.5\"  r=\"5\" fill=\"#facc15\" fill-opacity=\"0.90\"/>\n                <circle cx=\"37.5\"  cy=\"87.5\"  r=\"5\" fill=\"#facc15\" fill-opacity=\"0.90\"/>\n                <circle cx=\"137.5\" cy=\"87.5\"  r=\"5\" fill=\"#facc15\" fill-opacity=\"0.90\"/>\n                <circle cx=\"37.5\"  cy=\"137.5\" r=\"5\" fill=\"#facc15\" fill-opacity=\"0.90\"/>\n                <circle cx=\"137.5\" cy=\"137.5\" r=\"5\" fill=\"#facc15\" fill-opacity=\"0.90\"/>\n                <circle cx=\"62.5\"  cy=\"162.5\" r=\"5\" fill=\"#facc15\" fill-opacity=\"0.90\"/>\n                <circle cx=\"112.5\" cy=\"162.5\" r=\"5\" fill=\"#facc15\" fill-opacity=\"0.90\"/>\n\n                <!-- Kuda putih di d4 -->\n                <text x=\"87.5\" y=\"112.5\" font-size=\"22\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♘</text>\n\n                <!-- Label judul -->\n                <text x=\"100\" y=\"10\" font-size=\"7\" fill=\"white\"\n                      text-anchor=\"middle\" font-weight=\"bold\" opacity=\"0.90\">GERAKAN KUDA — POLA \"L\"</text>\n\n                <!-- Koordinat kolom -->\n                <text x=\"37.5\"  y=\"209\" font-size=\"5.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">b</text>\n                <text x=\"62.5\"  y=\"209\" font-size=\"5.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">c</text>\n                <text x=\"87.5\"  y=\"209\" font-size=\"5.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">d</text>\n                <text x=\"112.5\" y=\"209\" font-size=\"5.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">e</text>\n                <text x=\"137.5\" y=\"209\" font-size=\"5.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">f</text>\n                <text x=\"100\"   y=\"219\" font-size=\"7.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">♘ 8 KOTAK TUJUAN DARI TENGAH</text>\n            </svg>\n\n            <div style=\"display:flex;gap:8px;margin-top:4px;justify-content:center;flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:7.5px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#facc15;border-radius:2px;display:inline-block;opacity:.8\"></span>\n                    Kotak tujuan pola \"L\" (8 petak)\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Nilai: 3 Poin</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Kuda adalah bidak dengan nilai 3 poin dan memiliki pola gerakan yang paling tidak biasa di antara semua bidak dalam catur. Sementara bidak lain bergerak dalam garis lurus atau diagonal, kuda bergerak dalam pola yang membentuk huruf \"L\": dua kotak ke satu arah, lalu satu kotak ke sisi tegak lurusnya. Kombinasi ini bisa dilakukan ke delapan arah, menghasilkan maksimal delapan kotak yang bisa dijangkau dari satu posisi — seperti yang terlihat dalam diagram ketika kuda berada di tengah papan.\n                <br><br>\n                Keistimewaan paling menonjol dari kuda adalah kemampuannya melompati bidak lain. Ia adalah satu-satunya bidak dalam catur yang dapat melewati bidak kawan maupun lawan yang berdiri di jalurnya, tanpa peduli seberapa padat posisi di papan. Karena itu, kuda sangat berguna justru di awal permainan ketika papan masih penuh sesak dan bidak-bidak jarak jauh seperti gajah atau benteng belum memiliki ruang untuk bergerak.\n                <br><br>\n                Dalam hal menangkap, kuda bekerja berdasarkan petak akhir yang dituju, bukan jalur yang dilewati. Selama petak tujuannya ditempati oleh bidak lawan, kuda bisa menangkapnya meski melompati banyak bidak di tengah perjalanan. Inilah yang membuat serangan kuda sering terasa tiba-tiba dan sulit diantisipasi.\n                <br><br>\n                Namun kekuatan kuda sangat bergantung pada posisinya. Dari tengah papan, ia bisa menjangkau delapan kotak. Di tepi papan, jumlah itu berkurang menjadi empat. Di pojok, hanya dua kotak yang tersisa. Karena itu, kuda yang ditempatkan di pinggir papan jauh kurang efektif dibandingkan kuda yang ditempatkan di pusat, dan prinsip ini berlaku konsisten di hampir semua fase permainan.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <!-- Papan 8×8 -->\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect x=\"0\"   y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"150\" y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"100\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"150\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"175\" width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"175\" width=\"25\" height=\"25\"/>\n                </g>\n\n                <!-- Pemisah tengah vertikal -->\n                <line x1=\"100\" y1=\"0\" x2=\"100\" y2=\"200\"\n                      stroke=\"#9ca3af\" stroke-width=\"1\" stroke-dasharray=\"4,3\" opacity=\"0.55\"/>\n\n                <!-- === KIRI: Kuda di pojok a1 — hanya 2 kotak === -->\n                <!-- Label POJOK -->\n                <rect x=\"2\" y=\"2\" width=\"30\" height=\"8\" rx=\"2\" fill=\"#ef4444\" fill-opacity=\"0.85\"/>\n                <text x=\"17\" y=\"6.5\" font-size=\"4.5\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">POJOK</text>\n\n                <!--\n                    Kuda di a1 (12.5, 187.5)\n                    Tujuan dari a1:\n                    b3 (37.5, 137.5) — 1 kanan 2 atas ✓\n                    c2 (62.5, 162.5) — 2 kanan 1 atas ✓\n                    Hanya 2 kotak\n                -->\n                <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.45\"/>\n                <rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.45\"/>\n\n                <circle cx=\"37.5\" cy=\"137.5\" r=\"5\" fill=\"#D3D3D3\" fill-opacity=\"0.90\"/>\n                <circle cx=\"62.5\" cy=\"162.5\" r=\"5\" fill=\"#D3D3D3\" fill-opacity=\"0.90\"/>\n\n\n                <text x=\"12.5\" y=\"187.5\" font-size=\"20\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♘</text>\n\n                <!-- Label \"2 kotak\" -->\n                <rect x=\"2\" y=\"108\" width=\"44\" height=\"8\" rx=\"2\" fill=\"#ef4444\" fill-opacity=\"0.82\"/>\n                <text x=\"24\" y=\"112.5\" font-size=\"4.5\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">Hanya 2 kotak tujuan</text>\n\n                <!-- === KANAN: Kuda di e5 (tengah) — 8 kotak === -->\n                <!-- Label TENGAH -->\n                <rect x=\"148\" y=\"2\" width=\"48\" height=\"8\" rx=\"2\" fill=\"#16a34a\" fill-opacity=\"0.85\"/>\n                <text x=\"172\" y=\"6.5\" font-size=\"4.5\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">TENGAH</text>\n\n                <!--\n                    Kuda di e5 (112.5, 87.5) — tapi kita pakai sisi kanan saja\n                    Kuda di f4 (137.5, 112.5) agar cukup ruang di kanan papan\n                    f4→ tujuan:\n                    d3 (87.5,  137.5) — 2 kiri 1 bawah  ✓ (tapi x<100, masuk sisi kiri)\n                    \n                    Revisi: Kuda di f5 (137.5, 87.5)\n                    Tujuan:\n                    d4 (87.5,  112.5) — 2 kiri 1 bawah  — x=87.5 < 100 → masuk kiri, skip\n                    d6 (87.5,  62.5)  — 2 kiri 1 atas   — masuk kiri, skip\n                    e3 (112.5, 137.5) — 1 kiri 2 bawah  ✓\n                    e7 (112.5, 37.5)  — 1 kiri 2 atas   ✓\n                    g3 (162.5, 137.5) — 1 kanan 2 bawah ✓\n                    g7 (162.5, 37.5)  — 1 kanan 2 atas  ✓\n                    h4 (187.5, 112.5) — 2 kanan 1 bawah ✓\n                    h6 (187.5, 62.5)  — 2 kanan 1 atas  ✓\n                    Total 6 di sisi kanan, tapi tunjukkan semua yg valid\n\n                    Lebih baik: Kuda di f5 = (125, 75) center (137.5, 87.5)\n                    Semua 8 tujuan:\n                    d4: (75,100)   center(87.5, 112.5)  — masuk sisi kiri, lewati\n                    d6: (75, 50)   center(87.5,  62.5)  — masuk sisi kiri, lewati\n                    e3: (100,125)  center(112.5,137.5)  ✓\n                    e7: (100, 25)  center(112.5, 37.5)  ✓\n                    g3: (150,125)  center(162.5,137.5)  ✓\n                    g7: (150, 25)  center(162.5, 37.5)  ✓\n                    h4: (175,100)  center(187.5,112.5)  ✓\n                    h6: (175, 50)  center(187.5, 62.5)  ✓\n\n                    6 di sisi kanan → cukup untuk ilustrasi\n                    Kita tunjukkan semua 8, highlight yang di kanan lebih terang\n                -->\n\n                <!-- Tujuan f5 yang ada di sisi kanan (≥100) -->\n                <rect x=\"100\" y=\"125\" width=\"25\" height=\"25\" fill=\"#16a34a\" fill-opacity=\"0.45\"/>\n                <rect x=\"100\" y=\"25\"  width=\"25\" height=\"25\" fill=\"#16a34a\" fill-opacity=\"0.45\"/>\n                <rect x=\"150\" y=\"125\" width=\"25\" height=\"25\" fill=\"#16a34a\" fill-opacity=\"0.45\"/>\n                <rect x=\"150\" y=\"25\"  width=\"25\" height=\"25\" fill=\"#16a34a\" fill-opacity=\"0.45\"/>\n                <rect x=\"175\" y=\"100\" width=\"25\" height=\"25\" fill=\"#16a34a\" fill-opacity=\"0.45\"/>\n                <rect x=\"175\" y=\"50\"  width=\"25\" height=\"25\" fill=\"#16a34a\" fill-opacity=\"0.45\"/>\n                <!-- Tujuan yang melewati garis tengah (sedikit transparan) -->\n                <rect x=\"75\"  y=\"100\" width=\"25\" height=\"25\" fill=\"#16a34a\" fill-opacity=\"0.20\"/>\n                <rect x=\"75\"  y=\"50\"  width=\"25\" height=\"25\" fill=\"#16a34a\" fill-opacity=\"0.20\"/>\n\n                <!-- Titik tujuan kanan -->\n                <circle cx=\"112.5\" cy=\"137.5\" r=\"5\" fill=\"#D3D3D3\" fill-opacity=\"0.90\"/>\n                <circle cx=\"112.5\" cy=\"37.5\"  r=\"5\" fill=\"#D3D3D3\" fill-opacity=\"0.90\"/>\n                <circle cx=\"162.5\" cy=\"137.5\" r=\"5\" fill=\"#D3D3D3\" fill-opacity=\"0.90\"/>\n                <circle cx=\"162.5\" cy=\"37.5\"  r=\"5\" fill=\"#D3D3D3\" fill-opacity=\"0.90\"/>\n                <circle cx=\"187.5\" cy=\"112.5\" r=\"5\" fill=\"#D3D3D3\" fill-opacity=\"0.90\"/>\n                <circle cx=\"187.5\" cy=\"62.5\"  r=\"5\" fill=\"#D3D3D3\" fill-opacity=\"0.90\"/>\n                <!-- Titik tujuan yang melewati garis tengah -->\n                <circle cx=\"87.5\"  cy=\"112.5\" r=\"5\" fill=\"#D3D3D3\" fill-opacity=\"0.40\"/>\n                <circle cx=\"87.5\"  cy=\"62.5\"  r=\"5\" fill=\"#D3D3D3\" fill-opacity=\"0.40\"/>\n\n                <!-- Kuda putih di f5 -->\n                <text x=\"137.5\" y=\"87.5\" font-size=\"20\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♘</text>\n\n                <!-- Label \"8 kotak\" -->\n                <rect x=\"110\" y=\"108\" width=\"44\" height=\"8\" rx=\"2\" fill=\"#16a34a\" fill-opacity=\"0.82\"/>\n                <text x=\"132\" y=\"112.5\" font-size=\"4.5\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">Hingga 8 kotak tujuan</text>\n\n                <!-- Koordinat -->\n                <text x=\"12.5\"  y=\"209\" font-size=\"5.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">a1 ♘</text>\n                <text x=\"137.5\" y=\"209\" font-size=\"5.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">f5 ♘</text>\n                <text x=\"100\"   y=\"219\" font-size=\"7.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">♘ POJOK vs TENGAH — Pengaruh Posisi</text>\n            </svg>\n\n            <div style=\"display:flex;gap:8px;margin-top:4px;justify-content:center;flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:7.5px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#ef4444;border-radius:2px;display:inline-block;opacity:.7\"></span>\n                    Pojok (a1): hanya 2 kotak\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:7.5px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#16a34a;border-radius:2px;display:inline-block;opacity:.7\"></span>\n                    Tengah (f5): hingga 8 kotak\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Posisi Menentukan Kekuatan Kuda</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Tidak ada bidak lain dalam catur yang nilai praktisnya berubah sedrastis kuda tergantung di mana ia ditempatkan. Diagram di samping memperlihatkan perbedaan itu secara langsung. Kuda di pojok <strong>a1</strong> hanya memiliki dua kotak tujuan yang valid — bidak yang secara teoritis bernilai tiga poin tetapi kekuatan nyatanya jauh di bawah itu. Sementara kuda di <strong>f5</strong>, di dekat pusat papan, dapat menjangkau hingga delapan kotak sekaligus.\n                <br><br>\n                Perbedaan ini bukan sekadar soal jumlah. Kuda yang berada di tengah papan mengontrol lebih banyak petak penting, lebih sulit diusir oleh pion lawan, dan lebih mudah menjangkau semua sektor papan tanpa perlu banyak langkah tambahan. Kuda di tepi membutuhkan beberapa langkah hanya untuk bisa kembali aktif, dan dalam permainan yang bergerak cepat, langkah yang terbuang untuk reposisi adalah tempo yang sangat mahal.\n                <br><br>\n                Karena itu, ada ungkapan klasik dalam catur yang berbunyi: <em>\"A knight on the rim is dim\"</em> — kuda di tepi papan redup cahayanya. Prinsip ini bukan sekadar aksioma, tetapi mencerminkan matematika geometri papan yang memang tidak berpihak pada kuda yang terpinggirkan.\n                <br><br>\n                Dalam praktiknya, salah satu tujuan paling konsisten dalam pengembangan kuda adalah membawanya ke petak tengah yang kuat, terutama yang tidak mudah diserang oleh pion lawan. Kuda yang telah menduduki petak seperti itu — biasanya di e5, d5, f5, atau petak setara — sering kali menjadi bidak yang paling dominan di papan dan sangat sulit diusir tanpa membayar kerugian posisi yang berarti.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n    <div class=\"board-panel relative\" style=\"float: left; margin-right: 1.5rem; margin-bottom: 1rem;\">\n        <svg viewBox=\"0 0 200 230\" class=\"w-full h-full\">\n            <!-- Papan 8×8 -->\n            <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n            <g fill=\"#eeeed2\">\n                <rect x=\"0\"   y=\"175\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"175\" width=\"25\" height=\"25\"/>\n                <rect x=\"100\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"175\" width=\"25\" height=\"25\"/>\n                <rect x=\"25\"  y=\"150\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"150\" width=\"25\" height=\"25\"/>\n                <rect x=\"125\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"150\" width=\"25\" height=\"25\"/>\n                <rect x=\"0\"   y=\"125\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"125\" width=\"25\" height=\"25\"/>\n                <rect x=\"100\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"125\" width=\"25\" height=\"25\"/>\n                <rect x=\"25\"  y=\"100\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"100\" width=\"25\" height=\"25\"/>\n                <rect x=\"125\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"100\" width=\"25\" height=\"25\"/>\n                <rect x=\"0\"   y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"75\"  width=\"25\" height=\"25\"/>\n                <rect x=\"100\" y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"75\"  width=\"25\" height=\"25\"/>\n                <rect x=\"25\"  y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"50\"  width=\"25\" height=\"25\"/>\n                <rect x=\"125\" y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"50\"  width=\"25\" height=\"25\"/>\n                <rect x=\"0\"   y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"25\"  width=\"25\" height=\"25\"/>\n                <rect x=\"100\" y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"25\"  width=\"25\" height=\"25\"/>\n                <rect x=\"25\"  y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"0\"   width=\"25\" height=\"25\"/>\n                <rect x=\"125\" y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"175\" y=\"0\"   width=\"25\" height=\"25\"/>\n            </g>\n\n            <defs>\n                <marker id=\"arr-jump-l\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n                    <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#7c3aed\"/></marker>\n                <marker id=\"arr-jump-r\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n                    <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#7c3aed\"/></marker>\n            </defs>\n\n            <!--\n                Posisi awal standar baris 1 putih:\n                a1=♖  b1=♘  c1=♗  d1=♕  e1=♔  f1=♗  g1=♘  h1=♖\n\n                Kuda yang ditampilkan aktif: b1 (37.5, 187.5)\n                Tujuan L-move dari b1:\n                  a3 (12.5, 137.5) — 1 kiri 2 atas ✓\n                  c3 (62.5, 137.5) — 1 kanan 2 atas ✓\n                  d2 (87.5, 162.5) — 2 kanan 1 atas → ditempati pion kawan, skip\n\n                Kuda melompati pion baris 2 untuk mencapai a3 / c3\n            -->\n\n            <!-- Baris 2: pion putih (penghalang yang dilompati) -->\n            <text x=\"12.5\"  y=\"162.5\" font-size=\"17\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.55\">♙</text>\n            <text x=\"37.5\"  y=\"162.5\" font-size=\"17\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.55\">♙</text>\n            <text x=\"62.5\"  y=\"162.5\" font-size=\"17\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.55\">♙</text>\n            <text x=\"87.5\"  y=\"162.5\" font-size=\"17\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.55\">♙</text>\n            <text x=\"112.5\" y=\"162.5\" font-size=\"17\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.55\">♙</text>\n            <text x=\"137.5\" y=\"162.5\" font-size=\"17\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.55\">♙</text>\n            <text x=\"162.5\" y=\"162.5\" font-size=\"17\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.55\">♙</text>\n            <text x=\"187.5\" y=\"162.5\" font-size=\"17\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.55\">♙</text>\n\n            <!--\n                Baris 1: perwira putih (posisi awal benar)\n                a1=♖  b1=♘(aktif)  c1=♗  d1=♕  e1=♔  f1=♗  g1=♘  h1=♖\n            -->\n            <text x=\"12.5\"  y=\"187.5\" font-size=\"17\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.55\">♖</text>\n            <!-- b1 = kuda aktif, digambar terpisah di bawah -->\n            <text x=\"62.5\"  y=\"187.5\" font-size=\"17\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.55\">♗</text>\n            <text x=\"87.5\"  y=\"187.5\" font-size=\"17\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.55\">♕</text>\n            <text x=\"112.5\" y=\"187.5\" font-size=\"17\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.55\">♔</text>\n            <text x=\"137.5\" y=\"187.5\" font-size=\"17\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.55\">♗</text>\n            <text x=\"162.5\" y=\"187.5\" font-size=\"17\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.55\">♘</text>\n            <text x=\"187.5\" y=\"187.5\" font-size=\"17\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.55\">♖</text>\n\n            <!-- Highlight petak tujuan a3 dan c3 -->\n            <rect x=\"0\"  y=\"125\" width=\"25\" height=\"25\" fill=\"#7c3aed\" fill-opacity=\"0.35\"/>\n            <rect x=\"50\" y=\"125\" width=\"25\" height=\"25\" fill=\"#7c3aed\" fill-opacity=\"0.35\"/>\n\n            <!-- Titik tujuan -->\n           \n           <text x=\"12.5\" y=\"137.5\" font-size=\"20\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♘</text>\n           <text x=\"62.5\" y=\"137.5\" font-size=\"20\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♘</text>\n\n            <!--\n                PANAH LOMPATAN KUDA b1 (37.5,187.5):\n                Ke a3 (12.5,137.5) — kurva melengkung ke kiri atas\n                Ke c3 (62.5,137.5) — kurva melengkung ke kanan atas\n            -->\n\n            <!-- Panah kiri: b1 → a3 -->\n            <path d=\"M 37.5,180 C 25,148 14,148 12.5,142\"\n                  stroke=\"#7c3aed\" stroke-width=\"2.5\" fill=\"none\"\n                  stroke-dasharray=\"4,3\" stroke-linecap=\"round\"\n                  marker-end=\"url(#arr-jump-l)\"/>\n\n            <!-- Panah kanan: b1 → c3 -->\n            <path d=\"M 37.5,180 C 50,148 60,148 62.5,142\"\n                  stroke=\"#7c3aed\" stroke-width=\"2.5\" fill=\"none\"\n                  stroke-dasharray=\"4,3\" stroke-linecap=\"round\"\n                  marker-end=\"url(#arr-jump-r)\"/>\n\n            <!-- Highlight lingkaran posisi kuda b1 -->\n            <circle cx=\"37.5\" cy=\"187.5\" r=\"11\" fill=\"#7c3aed\" fill-opacity=\"0.18\"/>\n\n            <!-- Kuda putih b1 (bidak aktif) -->\n            <text x=\"37.5\" y=\"187.5\" font-size=\"20\" fill=\"white\"\n                  text-anchor=\"middle\" dominant-baseline=\"central\">♘</text>\n\n            <!-- Badge -->\n            <rect x=\"18\" y=\"150\" width=\"50\" height=\"8\" rx=\"3\" fill=\"#7c3aed\" fill-opacity=\"0.90\"/>\n            <text x=\"43\" y=\"154.5\" font-size=\"4.5\" fill=\"white\"\n                  text-anchor=\"middle\" dominant-baseline=\"central\"\n                  font-weight=\"bold\">Melompati pion!</text>\n\n            <!-- Koordinat kolom -->\n            <text x=\"12.5\"  y=\"212\" font-size=\"5.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">a</text>\n            <text x=\"37.5\"  y=\"212\" font-size=\"5.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">b</text>\n            <text x=\"62.5\"  y=\"212\" font-size=\"5.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">c</text>\n\n            <!-- Footer -->\n            <rect x=\"10\" y=\"218\" width=\"180\" height=\"10\" rx=\"3\" fill=\"#7c3aed\" fill-opacity=\"0.92\"/>\n            <text x=\"100\" y=\"224\" font-size=\"6.5\" fill=\"white\"\n                  text-anchor=\"middle\" dominant-baseline=\"central\"\n                  font-weight=\"bold\">♘ KUDA b1 MELOMPATI BARISAN PION</text>\n        </svg>\n\n        <div style=\"display:flex;gap:8px;margin-top:6px;justify-content:center;flex-wrap:wrap;\">\n            <span style=\"display:flex;align-items:center;gap:4px;font-size:7.5px;color:#555;\">\n                <span style=\"width:8px;height:8px;background:#7c3aed;border-radius:50%;display:inline-block;opacity:.8\"></span>\n                Loncatan kuda b1 → a3 / c3\n            </span>\n        </div>\n    </div>\n\n    <div class=\"text-content\">\n        <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Kemampuan Unik: Melompati Bidak Lain</h3>\n        <p class=\"text-gray-600 leading-relaxed text-sm\">\n            Diagram di samping menggambarkan salah satu momen paling khas dalam pembukaan catur. Papan masih penuh sesak dengan pion dan bidak yang belum bergerak, tetapi kuda di <strong>b1</strong> sudah bisa melompat ke <strong>a3</strong> atau <strong>c3</strong> tanpa terganggu oleh apapun yang berdiri di jalurnya. Pion di a2, b2, c2, dan bidak-bidak di sekelilingnya sama sekali tidak menghalangi gerakan kuda.\n            <br><br>\n            Inilah yang membuat kuda menjadi bidak yang sangat berharga di fase pembukaan. Ketika gajah masih terblok oleh pion sendiri, benteng belum memiliki kolom terbuka, dan ratu belum aman untuk dikeluarkan, kuda sudah bisa aktif dan menempati petak strategis sejak langkah pertama. Ia tidak perlu menunggu jalur dibersihkan karena ia tidak membutuhkan jalur sama sekali.\n            <br><br>\n            Kemampuan ini juga menjadikan serangan kuda sangat sulit diantisipasi, terutama bagi pemain yang kurang berpengalaman. Sebuah kuda yang terlihat terblok secara visual bisa tiba-tiba muncul di petak yang mengejutkan karena ia bergerak bukan melalui garis lurus, melainkan melalui lompatan. Bidak yang tampak \"aman\" karena dikelilingi banyak kawan bisa tetap menjadi target valid kuda dari arah yang tidak terduga.\n            <br><br>\n            <span class=\"bg-amber-50 border border-amber-200 px-2 py-1 rounded text-xs inline-block mt-1\">\n                ⚠️ <strong>Perlu diingat:</strong> Meski kuda bisa melompati bidak di tengah jalur, ia tetap tidak boleh mendarat di petak yang sudah ditempati bidak sendiri. Ia hanya bisa menangkap bidak lawan yang berada di petak tujuan akhirnya.\n            </span>\n        </p>\n    </div>\n</div>"}]},{"id":"panduan-3","bab":"bab-bidak","nomor":"3","judul":"♗ GAJAH (Bishop)","deskripsi":"Gajah adalah bidak catur yang bergerak secara diagonal dan memiliki jangkauan panjang. Pelajari aturan gerakan gajah, cara makan, dan mengapa sepasang gajah sangat kuat dalam permainan catur.","baris":[{"sub":false,"html":"<div class=\"content-row\">\n        <div class=\"board-panel relative\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <!-- Papan 8×8 -->\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect x=\"0\"   y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"150\" y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"100\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"150\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"175\" width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"175\" width=\"25\" height=\"25\"/>\n                </g>\n\n                <!--\n                    Gajah putih di d4 (87.5, 112.5)\n                    4 garis diagonal:\n                    Kanan-atas: e5(112.5,87.5) f6(137.5,62.5) g7(162.5,37.5) h8(187.5,12.5)\n                    Kiri-atas:  c5(62.5,87.5)  b6(37.5,62.5)  a7(12.5,37.5)\n                    Kanan-bawah: e3(112.5,137.5) f2(137.5,162.5) g1(162.5,187.5)\n                    Kiri-bawah:  c3(62.5,137.5) b2(37.5,162.5)  a1(12.5,187.5)\n                -->\n\n                <!-- Diagonal kanan-atas -->\n                <rect x=\"100\" y=\"75\"  width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.50\"/>\n                <rect x=\"125\" y=\"50\"  width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.50\"/>\n                <rect x=\"150\" y=\"25\"  width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.50\"/>\n                <rect x=\"175\" y=\"0\"   width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.50\"/>\n\n                <!-- Diagonal kiri-atas -->\n                <rect x=\"50\"  y=\"75\"  width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.50\"/>\n                <rect x=\"25\"  y=\"50\"  width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.50\"/>\n                <rect x=\"0\"   y=\"25\"  width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.50\"/>\n\n                <!-- Diagonal kanan-bawah -->\n                <rect x=\"100\" y=\"125\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.50\"/>\n                <rect x=\"125\" y=\"150\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.50\"/>\n                <rect x=\"150\" y=\"175\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.50\"/>\n\n                <!-- Diagonal kiri-bawah -->\n                <rect x=\"50\"  y=\"125\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.50\"/>\n                <rect x=\"25\"  y=\"150\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.50\"/>\n                <rect x=\"0\"   y=\"175\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.50\"/>\n\n                <!-- Gajah putih di d4 -->\n                <text x=\"87.5\" y=\"112.5\" font-size=\"22\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♗</text>\n\n                <!-- Label judul -->\n                <text x=\"100\" y=\"10\" font-size=\"7\" fill=\"white\"\n                      text-anchor=\"middle\" font-weight=\"bold\" opacity=\"0.90\">GERAKAN GAJAH — 4 DIAGONAL</text>\n\n                <!-- Koordinat -->\n                <text x=\"87.5\" y=\"209\" font-size=\"5.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">d4</text>\n                <text x=\"100\"  y=\"219\" font-size=\"7.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">♗ GAJAH — Bergerak Diagonal Tanpa Batas</text>\n            </svg>\n\n            <div style=\"display:flex;gap:8px;margin-top:4px;justify-content:center;flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:7.5px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#facc15;border-radius:2px;display:inline-block;opacity:.8\"></span>\n                    Jangkauan diagonal (4 arah, tanpa batas jarak)\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Nilai: 3 Poin</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Gajah adalah bidak dengan nilai 3 poin yang bergerak secara diagonal — empat arah miring sekaligus, dengan jangkauan sejauh yang ia mau selama tidak ada bidak yang menghalangi jalurnya. Dari posisi di tengah papan seperti <strong>d4</strong>, gajah bisa menjangkau hingga 13 petak sekaligus, menjadikannya salah satu bidak paling efisien untuk mengontrol ruang dari kejauhan.\n                <br><br>\n                Berbeda dari kuda, gajah tidak bisa melompati bidak lain. Jika ada bidak — kawan maupun lawan — yang berdiri di jalur diagonalnya, gajah harus berhenti sebelum bidak tersebut. Ia hanya bisa menangkap jika bidak penghalang itu adalah milik lawan, dan proses menangkapnya menghentikan gajah di petak itu. Karena sifat ini, gajah sangat bergantung pada struktur pion: dalam posisi tertutup di mana banyak pion saling mengunci, gajah bisa sangat terbatas. Namun di posisi terbuka, ia menjadi sangat dominan.\n                <br><br>\n                Satu ciri khas gajah yang paling penting untuk dipahami adalah bahwa ia terikat pada satu warna kotak sepanjang permainan. Gajah yang dimulai dari kotak putih tidak akan pernah bisa menapaki kotak hitam, dan sebaliknya. Inilah mengapa setiap pemain memulai permainan dengan dua gajah yang saling melengkapi — satu untuk kotak terang, satu untuk kotak gelap — dan kehilangan salah satu berarti kehilangan kontrol terhadap separuh warna papan secara permanen.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: left; margin-right: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <!-- Papan 8×8 -->\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect x=\"0\"   y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"150\" y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"100\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"150\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"100\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"175\" width=\"25\" height=\"25\"/>\n                    <rect x=\"125\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"175\" width=\"25\" height=\"25\"/>\n                </g>\n\n                <!--\n                    BISHOP PAIR:\n                    Gajah kotak terang di d5 (87.5, 87.5) — berdiri di kotak gelap\n                    Gajah kotak gelap di e4 (112.5, 112.5) — berdiri di kotak terang\n                    \n                    Wait: d5 pada papan SVG kita:\n                    d = kolom ke-4 = x=75, rank 5 = y=75 → d5 = (75,75) center (87.5,87.5)\n                    Petak d5: x=75,y=75 → (75+75)/25 = kolom 3 + baris 3 = 6 (genap) → kotak terang\n                    \n                    Gajah \"kotak terang\" harus berdiri di kotak terang dan hanya menjelajah kotak terang\n                    Gajah \"kotak gelap\" harus berdiri di kotak gelap dan hanya menjelajah kotak gelap\n                    \n                    d5 = kotak terang → gajah kotak terang ✓\n                    e4 = x=100,y=100 → (100+100)/25 = 4+4 = 8 (genap) → kotak terang juga ✗\n                    \n                    Let me recalculate:\n                    Kotak terang di SVG kita = kotak dengan fill #eeeed2\n                    Pattern: kotak (col,row) dimana col+row genap = terang\n                    col = x/25, row = y/25\n                    \n                    d5: x=75, y=75 → col=3, row=3 → 3+3=6 genap → TERANG ✓\n                    e4: x=100,y=100 → col=4, row=4 → 4+4=8 genap → TERANG ✗ (sama!)\n                    \n                    Untuk bishop pair, saya butuh satu di kotak terang, satu di kotak gelap:\n                    c4: x=50, y=100 → col=2, row=4 → 2+4=6 genap → TERANG\n                    d4: x=75, y=100 → col=3, row=4 → 3+4=7 ganjil → GELAP ✓\n                    \n                    Jadi: gajah terang di d5 (87.5, 87.5)\n                          gajah gelap di e4 (112.5, 112.5)? → e4 terang, salah\n                          gajah gelap di d4 (87.5, 112.5) → gelap ✓\n                    \n                    Tapi kalau keduanya di kolom d, kurang visual menarik.\n                    \n                    Pakai: gajah terang di c5 (62.5, 87.5) → c5: col=2,row=3 → 5 ganjil → GELAP ✗\n                    \n                    c5: x=50, y=75 → col=2, row=3 → 2+3=5 ganjil → GELAP\n                    d5: x=75, y=75 → col=3, row=3 → 6 genap → TERANG\n                    e5: x=100,y=75 → col=4, row=3 → 7 ganjil → GELAP\n                    f5: x=125,y=75 → col=5, row=3 → 8 genap → TERANG\n                    \n                    Pakai:\n                    Gajah kotak TERANG di d5 (87.5, 87.5) → kotak terang ✓\n                    Gajah kotak GELAP di e4 → salah\n                    Gajah kotak GELAP di c4 → c4: x=50,y=100 → col=2,row=4 → 6 genap → TERANG ✗\n                    \n                    d4: col=3,row=4 → 7 ganjil → GELAP ✓\n                    e5: col=4,row=3 → 7 ganjil → GELAP ✓\n                    \n                    OK pakai:\n                    Gajah TERANG di d5 (87.5, 87.5) — kotak terang ✓\n                    Gajah GELAP di e4 ... no\n                    \n                    e5 → gelap ✓ tapi terlalu dekat d5\n                    \n                    Pakai jarak lebih jauh:\n                    Gajah TERANG di b3 (37.5, 137.5) → col=1,row=5 → 6 genap → TERANG ✓\n                    Gajah GELAP di f4 (137.5, 112.5) → col=5,row=4 → 9 ganjil → GELAP ✓\n                    \n                    OK! Sekarang highlight diagonal masing-masing:\n                    \n                    Gajah terang b3: diagonal terang saja\n                    Gajah gelap f4: diagonal gelap saja\n                    \n                    Dengan warna berbeda: biru untuk terang, oranye untuk gelap\n                -->\n\n                <!-- Diagonal gajah TERANG di b3 (37.5, 137.5) — warna biru -->\n                <!-- Kanan-atas: c4(62.5,112.5) d5(87.5,87.5) e6(112.5,62.5) f7(137.5,37.5) g8(162.5,12.5) -->\n                <rect x=\"50\"  y=\"100\" width=\"25\" height=\"25\" fill=\"#3b82f6\" fill-opacity=\"0.30\"/>\n                <rect x=\"75\"  y=\"75\"  width=\"25\" height=\"25\" fill=\"#3b82f6\" fill-opacity=\"0.30\"/>\n                <rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\" fill=\"#3b82f6\" fill-opacity=\"0.30\"/>\n                <rect x=\"125\" y=\"25\"  width=\"25\" height=\"25\" fill=\"#3b82f6\" fill-opacity=\"0.30\"/>\n                <rect x=\"150\" y=\"0\"   width=\"25\" height=\"25\" fill=\"#3b82f6\" fill-opacity=\"0.30\"/>\n                <!-- Kiri-atas: a4(12.5,112.5) -->\n                <rect x=\"0\"   y=\"100\" width=\"25\" height=\"25\" fill=\"#3b82f6\" fill-opacity=\"0.30\"/>\n                <!-- Kanan-bawah: c2(62.5,162.5) d1(87.5,187.5) -->\n                <rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\" fill=\"#3b82f6\" fill-opacity=\"0.30\"/>\n                <rect x=\"75\"  y=\"175\" width=\"25\" height=\"25\" fill=\"#3b82f6\" fill-opacity=\"0.30\"/>\n                <!-- Kiri-bawah: a1(12.5,187.5) -->\n                <rect x=\"0\"   y=\"175\" width=\"25\" height=\"25\" fill=\"#3b82f6\" fill-opacity=\"0.30\"/>\n\n                <!-- Diagonal gajah GELAP di f4 (137.5, 112.5) — warna oranye -->\n                <!-- Kanan-atas: g5(162.5,87.5) h6(187.5,62.5) -->\n                <rect x=\"150\" y=\"75\"  width=\"25\" height=\"25\" fill=\"#f97316\" fill-opacity=\"0.30\"/>\n                <rect x=\"175\" y=\"50\"  width=\"25\" height=\"25\" fill=\"#f97316\" fill-opacity=\"0.30\"/>\n                <!-- Kiri-atas: e5(112.5,87.5) d6(87.5,62.5) c7(62.5,37.5) b8(37.5,12.5) -->\n                <rect x=\"100\" y=\"75\"  width=\"25\" height=\"25\" fill=\"#f97316\" fill-opacity=\"0.30\"/>\n                <rect x=\"75\"  y=\"50\"  width=\"25\" height=\"25\" fill=\"#f97316\" fill-opacity=\"0.30\"/>\n                <rect x=\"50\"  y=\"25\"  width=\"25\" height=\"25\" fill=\"#f97316\" fill-opacity=\"0.30\"/>\n                <rect x=\"25\"  y=\"0\"   width=\"25\" height=\"25\" fill=\"#f97316\" fill-opacity=\"0.30\"/>\n                <!-- Kanan-bawah: g3(162.5,137.5) h2(187.5,162.5) -->\n                <rect x=\"150\" y=\"125\" width=\"25\" height=\"25\" fill=\"#f97316\" fill-opacity=\"0.30\"/>\n                <rect x=\"175\" y=\"150\" width=\"25\" height=\"25\" fill=\"#f97316\" fill-opacity=\"0.30\"/>\n                <!-- Kiri-bawah: e3(112.5,137.5) d2(87.5,162.5) c1(62.5,187.5) -->\n                <rect x=\"100\" y=\"125\" width=\"25\" height=\"25\" fill=\"#f97316\" fill-opacity=\"0.30\"/>\n                <rect x=\"75\"  y=\"150\" width=\"25\" height=\"25\" fill=\"#f97316\" fill-opacity=\"0.30\"/>\n                <rect x=\"50\"  y=\"175\" width=\"25\" height=\"25\" fill=\"#f97316\" fill-opacity=\"0.30\"/>\n\n                <!-- Gajah terang di b3 -->\n                <text x=\"37.5\"  y=\"137.5\" font-size=\"20\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♗</text>\n                <!-- Gajah gelap di f4 -->\n                <text x=\"137.5\" y=\"112.5\" font-size=\"20\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♗</text>\n\n                <!-- Label gajah -->\n                <rect x=\"15\" y=\"118\" width=\"44\" height=\"8\" rx=\"2\" fill=\"#3b82f6\" fill-opacity=\"0.88\"/>\n                <text x=\"37\" y=\"122.5\" font-size=\"4.5\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">♗ Kotak terang</text>\n\n                <rect x=\"115\" y=\"96\" width=\"44\" height=\"8\" rx=\"2\" fill=\"#f97316\" fill-opacity=\"0.88\"/>\n                <text x=\"137\" y=\"100.5\" font-size=\"4.5\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">♗ Kotak gelap</text>\n\n                <!-- Koordinat -->\n                <text x=\"37.5\"  y=\"209\" font-size=\"5.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">b3 ♗</text>\n                <text x=\"137.5\" y=\"209\" font-size=\"5.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">f4 ♗</text>\n                <text x=\"100\"   y=\"219\" font-size=\"7.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">♗♗ BISHOP PAIR — Kontrol Dua Warna</text>\n            </svg>\n\n            <div style=\"display:flex;gap:8px;margin-top:4px;justify-content:center;flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:7.5px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#3b82f6;border-radius:2px;display:inline-block;opacity:.7\"></span>\n                    Gajah kotak terang (b3)\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:7.5px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#f97316;border-radius:2px;display:inline-block;opacity:.7\"></span>\n                    Gajah kotak gelap (f4)\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Sepasang Gajah — Bishop Pair</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Karena setiap gajah terikat pada satu warna kotak sepanjang permainan, memiliki keduanya berarti menguasai seluruh papan secara diagonal. Diagram di samping memperlihatkan bagaimana dua gajah yang bekerja bersama saling melengkapi: gajah di <strong>b3</strong> menguasai diagonal kotak terang (biru), sementara gajah di <strong>f4</strong> menguasai diagonal kotak gelap (oranye). Tidak ada satu petak diagonal pun di papan yang luput dari jangkauan keduanya.\n                <br><br>\n                Inilah yang disebut <em>bishop pair</em> — sepasang gajah yang dimiliki satu pihak sementara lawan sudah kehilangan salah satu gajahnya. Keunggulan <em>bishop pair</em> adalah keunggulan jangka panjang yang nilainya meningkat seiring permainan berlanjut. Di middlegame yang terbuka dan terutama di endgame ketika pion semakin sedikit, dua gajah dapat mengontrol lebih banyak petak dari jarak jauh dibandingkan hampir semua kombinasi bidak minor lainnya.\n                <br><br>\n                Sebaliknya, gajah tunggal memiliki kelemahan struktural yang tidak bisa diatasi: ia tidak pernah bisa menyentuh separuh kotak di papan. Jika lawan menempatkan pion dan bidaknya di warna kotak yang tidak bisa dijangkau oleh gajah kita, maka gajah itu menjadi hampir tidak berguna meskipun masih berada di papan.\n                <br><br>\n                <span class=\"bg-blue-50 border border-blue-200 px-2 py-1 rounded text-xs inline-block mt-1\">\n                    💡 <strong>Prinsip praktis:</strong> Jika kamu memiliki <em>bishop pair</em> dan lawan tidak, usahakan membuka posisi — tukarkan pion, bersihkan tengah papan. Semakin terbuka posisi, semakin dominan dua gajahmu dibandingkan bidak minor lawan.\n                </span>\n            </p>\n        </div>\n    </div>"}]},{"id":"panduan-4","bab":"bab-bidak","nomor":"4","judul":"♖ BENTENG (Rook)","deskripsi":"Benteng adalah bidak catur yang sangat kuat dengan gerakan lurus horizontal dan vertikal. Pelajari cara gerak benteng, cara makan, dan alasan mengapa benteng sangat berbahaya di kolom terbuka.","baris":[{"sub":false,"html":"<div class=\"content-row\">\n                <div class=\"board-panel relative\" style=\"float: left; margin-right: 1.5rem; margin-bottom: 1rem;\">\n                    <svg viewBox=\"0 0 200 200\" class=\"w-full h-full\">\n                        <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                        <g fill=\"#eeeed2\"><rect width=\"25\" height=\"25\" x=\"0\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"25\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"0\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"25\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"0\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"25\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"0\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"25\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"175\"/></g>\n                        <rect x=\"50\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"25\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"0\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"125\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"150\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"175\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"100\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"125\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"150\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"175\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"75\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"50\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"25\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"0\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <text x=\"87.5\" y=\"112.5\" font-size=\"20\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♖</text>\n                    </svg>\n                </div>\n                    <div class=\"text-content\">\n                        <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Nilai: 5 poin</h3>\n                        <p class=\"text-gray-600 leading-relaxed text-sm\"><strong>Benteng adalah bidak catur dengan nilai 5 poin</strong> dan termasuk salah satu bidak terkuat dalam permainan. Benteng bergerak lurus, baik secara horizontal maupun vertikal, dan dapat melangkah sejauh mungkin selama jalurnya tidak dihalangi bidak lain.  <br><br>Seperti gajah dan ratu, benteng tidak dapat melompati bidak lain. Untuk menangkap bidak lawan, benteng harus memiliki jalur lurus yang terbuka menuju bidak tersebut, lalu berhenti di kotak yang ditempati lawan itu.  <br><br>Pada awal permainan, benteng biasanya belum terlalu aktif karena posisinya berada di sudut papan dan sering terhalang oleh pion. Namun saat permainan mulai terbuka, terutama ketika kolom-kolom pion mulai kosong, benteng menjadi sangat berbahaya. Benteng sangat kuat jika ditempatkan di kolom terbuka, yaitu kolom tanpa pion, karena ia dapat menekan pertahanan lawan dari jarak jauh.  <br><br>Selain fungsi menyerang, benteng juga punya peran penting dalam pertahanan dan keselamatan raja melalui langkah khusus yang disebut rokade. Dalam strategi catur, benteng sering menjadi kekuatan utama di fase tengah hingga akhir permainan.  <br><br>Memahami cara gerak benteng sangat penting karena bidak ini sering menjadi kunci untuk menembus pertahanan lawan dan menguasai garis permainan.</p>\n                    </div>\n                </div>"}]},{"id":"panduan-5","bab":"bab-bidak","nomor":"5","judul":"♕ RATU (Queen)","deskripsi":"Ratu adalah bidak terkuat dalam permainan catur karena mampu bergerak lurus dan diagonal sekaligus. Pelajari gerakan ratu, cara makan, dan tips menggunakan ratu dengan efektif.","baris":[{"sub":false,"html":"<div class=\"content-row\">\n                <div class=\"board-panel relative\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n                    <svg viewBox=\"0 0 200 200\" class=\"w-full h-full\">\n                        <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                        <g fill=\"#eeeed2\"><rect width=\"25\" height=\"25\" x=\"0\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"25\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"0\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"25\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"0\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"25\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"0\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"25\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"175\"/></g>\n                        <rect x=\"50\" y=\"75\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"50\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"50\" y=\"125\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"125\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"100\" y=\"125\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"100\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"100\" y=\"75\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"75\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"50\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"25\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"0\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"125\" y=\"50\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"150\" y=\"25\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"175\" y=\"0\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"125\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"175\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"125\" y=\"150\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"150\" y=\"175\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"150\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"175\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"25\" y=\"150\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"0\" y=\"175\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"25\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"0\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"25\" y=\"50\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"0\" y=\"25\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <text x=\"87.5\" y=\"112.5\" font-size=\"20\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♕</text>\n                    </svg>\n                </div>\n                    <div class=\"text-content\">\n                        <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Nilai: 9 poin</h3>\n                        <p class=\"text-gray-600 leading-relaxed text-sm\"><strong>Ratu adalah bidak catur dengan nilai 9 poin</strong> dan dikenal sebagai bidak paling kuat dalam permainan. Kekuatan ratu berasal dari kemampuannya yang menggabungkan gerakan benteng dan gajah. Artinya, ratu dapat bergerak lurus secara horizontal maupun vertikal, sekaligus bergerak diagonal ke segala arah.  <br><br>Ratu bisa melangkah sejauh mungkin selama jalurnya tidak terhalang oleh bidak lain. Untuk menangkap bidak lawan, ratu menempati kotak yang dihuni lawan tersebut, baik melalui jalur lurus maupun diagonal. Namun seperti benteng dan gajah, ratu tidak dapat melompati bidak lain.  <br><br>Karena jangkauan geraknya sangat luas, ratu bisa menyerang banyak area papan sekaligus. Hal ini membuat ratu sangat berbahaya dalam serangan langsung ke raja lawan, menekan bidak penting, maupun membantu pertahanan. Tidak heran jika ratu sering menjadi bidak paling menentukan dalam pertandingan catur.  <br><br>Meski sangat kuat, ratu tidak sebaiknya dikeluarkan terlalu awal tanpa perhitungan. Jika terlalu cepat aktif, ratu bisa menjadi sasaran serangan bidak lawan dan memaksa pemain kehilangan tempo. Oleh karena itu, penggunaan ratu harus tetap bijak dan terukur.  <br><br>Memahami cara gerak ratu sangat penting bagi pemain yang ingin meningkatkan kemampuan strategi dan taktik dalam catur, karena ratu sering menjadi pusat kekuatan serangan maupun pertahanan.</p>\n                    </div>\n                </div>"}]},{"id":"panduan-6","bab":"bab-bidak","nomor":"6","judul":"♔ RAJA (King)","deskripsi":"Raja adalah bidak terpenting dalam permainan catur. Pelajari cara gerak raja, aturan agar tidak masuk ke kotak yang diserang lawan, serta peran rokade untuk menjaga keselamatan raja.","baris":[{"sub":false,"html":"<div class=\"content-row\">\n                <div class=\"board-panel relative\" style=\"float: left; margin-right: 1.5rem; margin-bottom: 1rem;\">\n                    <svg viewBox=\"0 0 200 200\" class=\"w-full h-full\">\n                        <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                        <g fill=\"#eeeed2\"><rect width=\"25\" height=\"25\" x=\"0\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"25\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"0\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"25\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"0\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"25\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"0\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"25\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"175\"/></g>\n                        <rect x=\"50\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"50\" y=\"75\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"50\" y=\"125\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"125\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"100\" y=\"125\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"100\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"100\" y=\"75\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <rect x=\"75\" y=\"75\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                        <text x=\"87.5\" y=\"112.5\" font-size=\"20\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♔</text>\n                    </svg>\n                </div>\n                    <div class=\"text-content\">\n                        <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Nilai: TAK TERHINGGA</h3>\n                        <p class=\"text-gray-600 leading-relaxed text-sm\"><strong>Raja adalah bidak paling penting dalam permainan catur</strong>. Tidak seperti bidak lain yang dinilai berdasarkan poin, raja memiliki nilai tak terhingga karena tidak boleh hilang. Tujuan utama permainan catur adalah menyerang raja lawan hingga tidak memiliki langkah aman lagi, atau yang dikenal sebagai skakmat.  <br><br>Dalam pergerakannya, raja hanya bisa melangkah 1 kotak ke segala arah, baik secara horizontal, vertikal, maupun diagonal. Meskipun langkahnya pendek, posisi raja sangat menentukan jalannya permainan, karena seluruh strategi bertahan dan menyerang pada akhirnya selalu berkaitan dengan keselamatan raja.  <br><br>Ada satu aturan penting yang harus selalu diingat: raja tidak boleh bergerak ke kotak yang sedang diserang oleh bidak lawan. Jika raja sedang berada dalam ancaman langsung, kondisi ini disebut skak. Dalam situasi skak, pemain wajib segera menyelamatkan raja, baik dengan memindahkannya, menutup serangan, atau menangkap bidak lawan yang menyerang.  <br><br>Raja juga memiliki langkah khusus bernama rokade, yaitu gerakan bersama benteng untuk memindahkan raja ke posisi yang lebih aman. Rokade menjadi salah satu cara penting untuk melindungi raja pada fase awal permainan.  <br><br>Pada awal dan pertengahan permainan, raja biasanya dijaga ketat karena rentan diserang. Namun di akhir permainan, raja justru sering menjadi lebih aktif dan ikut membantu menyerang serta mendukung pion menuju promosi. Karena itu, memahami gerakan raja adalah bagian penting dalam menguasai aturan dasar catur dan strategi permainan secara keseluruhan.</p>\n                    </div>\n                </div>"}]},{"id":"panduan-7","bab":"bab-bidak","nomor":"7","judul":"Nilai Bidak dalam Catur dan Cara Menghitung Pertukaran Material","deskripsi":"Memahami nilai setiap bidak catur sangat penting agar pemain tidak rugi dalam pertukaran. Pelajari tabel nilai bidak dari pion hingga ratu, serta prinsip dasar pertukaran material yang menguntungkan.","baris":[{"sub":false,"html":"<div class=\"content-row\">\n        <div class=\"board-panel table-panel\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n            <table class=\"w-full text-left text-sm text-gray-700 border border-gray-300\">\n                <thead class=\"bg-gray-100\">\n                    <tr>\n                        <th class=\"border border-gray-300 px-3 py-2 text-left\">Bidak</th>\n                        <th class=\"border border-gray-300 px-3 py-2 text-left\">Nilai</th>\n                        <th class=\"border border-gray-300 px-3 py-2 text-left\">Perbandingan</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td class=\"border border-gray-300 px-3 py-2\">♟ Pion</td><td class=\"border border-gray-300 px-3 py-2\">1</td><td class=\"border border-gray-300 px-3 py-2\">Satuan dasar</td></tr>\n                    <tr><td class=\"border border-gray-300 px-3 py-2\">♞ Kuda</td><td class=\"border border-gray-300 px-3 py-2\">3</td><td class=\"border border-gray-300 px-3 py-2\">= 3 Pion</td></tr>\n                    <tr><td class=\"border border-gray-300 px-3 py-2\">♗ Gajah</td><td class=\"border border-gray-300 px-3 py-2\">3</td><td class=\"border border-gray-300 px-3 py-2\">= 3 Pion</td></tr>\n                    <tr><td class=\"border border-gray-300 px-3 py-2\">♖ Benteng</td><td class=\"border border-gray-300 px-3 py-2\">5</td><td class=\"border border-gray-300 px-3 py-2\">= 5 Pion</td></tr>\n                    <tr><td class=\"border border-gray-300 px-3 py-2\">♕ Ratu</td><td class=\"border border-gray-300 px-3 py-2\">9</td><td class=\"border border-gray-300 px-3 py-2\">= 9 Pion</td></tr>\n                    <tr><td class=\"border border-gray-300 px-3 py-2\">♔ Raja</td><td class=\"border border-gray-300 px-3 py-2\">∞</td><td class=\"border border-gray-300 px-3 py-2\">Tak ternilai</td></tr>\n                </tbody>\n            </table>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Tabel Nilai Bidak dan Prinsip Pertukaran dalam Catur</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Dalam permainan catur, setiap bidak memiliki nilai material yang dijadikan acuan untuk menilai apakah sebuah pertukaran menguntungkan atau merugikan. Nilai ini bukan bagian dari aturan resmi permainan, melainkan panduan strategis yang sudah digunakan secara luas oleh pemain di seluruh dunia sebagai alat bantu pengambilan keputusan di papan. Memahami nilai-nilai ini dengan baik adalah fondasi dari hampir seluruh pertimbangan material dalam catur.\n                <br><br>\n                Pion memiliki nilai satu poin dan berfungsi sebagai satuan dasar dalam sistem perhitungan material. Kuda dan gajah masing-masing bernilai tiga poin, sehingga keduanya setara secara nilai meskipun memiliki karakter yang sangat berbeda dalam permainan — kuda lebih efektif di posisi tertutup dengan banyak pion di tengah, sedangkan gajah lebih dominan di papan terbuka dengan diagonal panjang yang tidak terhalang. Benteng bernilai lima poin dan secara signifikan lebih berharga dari bidak-bidak minor. Ratu adalah bidak aktif terkuat dengan nilai sembilan poin. Sementara raja tidak memiliki nilai poin karena ia tidak boleh hilang dalam kondisi apa pun — kehilangan raja berarti berakhirnya permainan.\n                <br><br>\n                Dengan memahami nilai ini, pemain dapat menghitung secara cepat apakah sebuah pertukaran bidak menguntungkan atau tidak. Sebuah pertukaran dikatakan menguntungkan ketika bidak yang berhasil ditangkap memiliki nilai lebih tinggi dari bidak yang dikorbankan untuk melakukan penangkapan tersebut. Misalnya, jika kuda bernilai tiga poin berhasil menangkap benteng bernilai lima poin, pemain mendapat keuntungan material bersih sebesar dua poin — kondisi yang dalam terminologi catur disebut sebagai <em>winning the exchange</em>.\n                <br><br>\n                Sebaliknya, pertukaran menjadi merugikan ketika bidak yang dikorbankan memiliki nilai lebih tinggi dari yang didapat. Mengorbankan ratu bernilai sembilan poin hanya untuk mendapatkan gajah bernilai tiga poin adalah kerugian material yang sangat besar dan hampir selalu sulit dipulihkan, kecuali ada kompensasi posisional atau taktis yang sangat konkret dan terkalkulasi dengan baik. Adapun pertukaran yang setara — misalnya kuda ditukar dengan gajah, atau benteng ditukar dengan benteng — tidak menghasilkan keuntungan material bagi siapapun, meskipun posisi di papan tetap bisa berubah secara signifikan tergantung pada siapa yang mendapatkan posisi lebih aktif setelah pertukaran tersebut.\n                <br><br>\n                Bagi pemula, prinsip yang paling penting adalah tidak pernah meninggalkan bidak berharga tanpa perlindungan, dan selalu menghitung nilai bidak yang terlibat sebelum memutuskan apakah sebuah pertukaran layak dilakukan. Keunggulan material yang dibangun secara konsisten sepanjang permainan hampir selalu menjadi salah satu faktor penentu kemenangan di level awal, karena kemampuan teknis untuk mengkonversi keunggulan tersebut menjadi kemenangan nyata biasanya masih jauh lebih mudah dicapai dibandingkan pada level yang lebih tinggi.\n            </p>\n        </div>\n    </div>"}]}];
